// Package postgres implements task.Repository against PostgreSQL via
// jackc/pgx. The queries are generated by sqlc from queries.sql.
package postgres

import (
	"context"
	"errors"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/cowork/internal/task"
	"github.com/garamsh/garam/cowork/internal/task/postgres/db"
	"github.com/garamsh/garam/platform/sdk/errorx"
	"github.com/garamsh/garam/platform/sdk/grn"
)

// foreignKeyViolation is the SQL state of a reference to a task that
// is gone.
const foreignKeyViolation = "23503"

// The kinds of object a link names, as task_links stores them.
const (
	linkPage    = "page"
	linkMessage = "message"
)

// Repository implements task.Repository against PostgreSQL.
type Repository struct {
	pool *pgxpool.Pool
}

var _ task.Repository = (*Repository)(nil)

// New answers a repository over pool.
func New(pool *pgxpool.Pool) *Repository {
	return &Repository{pool: pool}
}

func translate(err error, op string) error {
	switch {
	case err == nil:
		return nil
	case errors.Is(err, pgx.ErrNoRows):
		return task.ErrTaskNotFound
	case errorx.KindOf(err) != errorx.KindUnknown:
		return err
	}
	return errorx.Wrap(err, "tasks: "+op, errorx.KindUnavailable)
}

func text(s string) pgtype.Text { return pgtype.Text{String: s, Valid: s != ""} }

func assignee(g grn.GRN) pgtype.Text {
	if g.IsZero() {
		return pgtype.Text{}
	}
	return text(g.String())
}

func due(s string) (pgtype.Date, error) {
	if s == "" {
		return pgtype.Date{}, nil
	}
	d, err := time.Parse(task.DateLayout, s)
	if err != nil {
		return pgtype.Date{}, task.ErrInvalidTask
	}
	return pgtype.Date{Time: d, Valid: true}, nil
}

func timestamp(t time.Time) pgtype.Timestamptz { return pgtype.Timestamptz{Time: t, Valid: true} }

func taskOf(r db.Task) (task.Task, error) {
	creator, err := grn.Parse(r.CreatedBy)
	if err != nil {
		return task.Task{}, errorx.Wrap(err, "tasks: stored creator", errorx.KindDataLoss)
	}
	t := task.Task{
		ID: r.ID, Org: r.Org, Title: r.Title, Description: r.Description, Status: task.Status(r.Status),
		CreatedBy: creator, CreatedAt: r.CreatedAt.Time, UpdatedAt: r.UpdatedAt.Time,
		Pages: []string{}, Messages: []string{},
	}
	if r.Assignee.Valid {
		if t.Assignee, err = grn.Parse(r.Assignee.String); err != nil {
			return task.Task{}, errorx.Wrap(err, "tasks: stored assignee", errorx.KindDataLoss)
		}
	}
	if r.Due.Valid {
		t.Due = r.Due.Time.Format(task.DateLayout)
	}
	return t, nil
}

// writeLinks replaces t's links within tx.
func writeLinks(ctx context.Context, q *db.Queries, t task.Task) error {
	if err := q.DeleteLinks(ctx, db.DeleteLinksParams{Org: t.Org, TaskID: t.ID}); err != nil {
		return err
	}
	for kind, targets := range map[string][]string{linkPage: t.Pages, linkMessage: t.Messages} {
		for _, target := range targets {
			if err := q.InsertLink(ctx, db.InsertLinkParams{Org: t.Org, TaskID: t.ID, Kind: kind, Target: target}); err != nil {
				return err
			}
		}
	}
	return nil
}

// Create implements task.Repository.
func (r *Repository) Create(ctx context.Context, t task.Task) error {
	d, err := due(t.Due)
	if err != nil {
		return err
	}
	err = pgx.BeginFunc(ctx, r.pool, func(tx pgx.Tx) error {
		q := db.New(tx)
		if err := q.InsertTask(ctx, db.InsertTaskParams{
			Org: t.Org, ID: t.ID, Title: t.Title, Description: t.Description, Status: string(t.Status),
			Assignee: assignee(t.Assignee), Due: d, CreatedBy: t.CreatedBy.String(),
			CreatedAt: timestamp(t.CreatedAt), UpdatedAt: timestamp(t.UpdatedAt),
		}); err != nil {
			return err
		}
		return writeLinks(ctx, q, t)
	})
	return translate(err, "create")
}

// Update implements task.Repository.
func (r *Repository) Update(ctx context.Context, t task.Task) error {
	d, err := due(t.Due)
	if err != nil {
		return err
	}
	err = pgx.BeginFunc(ctx, r.pool, func(tx pgx.Tx) error {
		q := db.New(tx)
		n, err := q.UpdateTask(ctx, db.UpdateTaskParams{
			Org: t.Org, ID: t.ID, Title: t.Title, Description: t.Description, Status: string(t.Status),
			Assignee: assignee(t.Assignee), Due: d, UpdatedAt: timestamp(t.UpdatedAt),
		})
		if err != nil {
			return err
		}
		if n == 0 {
			return task.ErrTaskNotFound
		}
		return writeLinks(ctx, q, t)
	})
	return translate(err, "update")
}

// withLinks reads the links of rows and answers them as tasks.
func withLinks(ctx context.Context, q *db.Queries, org string, rows []db.Task) ([]task.Task, error) {
	out := make([]task.Task, len(rows))
	index := make(map[string]int, len(rows))
	ids := make([]string, len(rows))
	for i, row := range rows {
		t, err := taskOf(row)
		if err != nil {
			return nil, err
		}
		out[i], index[row.ID], ids[i] = t, i, row.ID
	}
	links, err := q.ListLinksOf(ctx, db.ListLinksOfParams{Org: org, Tasks: ids})
	if err != nil {
		return nil, err
	}
	for _, l := range links {
		t := &out[index[l.TaskID]]
		switch l.Kind {
		case linkPage:
			t.Pages = append(t.Pages, l.Target)
		case linkMessage:
			t.Messages = append(t.Messages, l.Target)
		}
	}
	return out, nil
}

// Get implements task.Repository.
func (r *Repository) Get(ctx context.Context, org, id string) (task.Task, error) {
	q := db.New(r.pool)
	row, err := q.GetTask(ctx, db.GetTaskParams{Org: org, ID: id})
	if err != nil {
		return task.Task{}, translate(err, "get")
	}
	ts, err := withLinks(ctx, q, org, []db.Task{row})
	if err != nil {
		return task.Task{}, translate(err, "get")
	}
	return ts[0], nil
}

// List implements task.Repository.
func (r *Repository) List(ctx context.Context, org string, f task.Filter, limit int) ([]task.Task, error) {
	q := db.New(r.pool)
	rows, err := q.ListTasks(ctx, db.ListTasksParams{
		Org: org, Status: text(string(f.Status)), Assignee: assignee(f.Assignee),
		Page: text(f.Page), Message: text(f.Message), Lim: int32(limit),
	})
	if err != nil {
		return nil, translate(err, "list")
	}
	ts, err := withLinks(ctx, q, org, rows)
	return ts, translate(err, "list")
}

// AddComment implements task.Repository. A comment on a task that is
// gone is the task's not being found.
func (r *Repository) AddComment(ctx context.Context, c task.Comment) error {
	err := db.New(r.pool).InsertComment(ctx, db.InsertCommentParams{
		Org: c.Org, ID: c.ID, TaskID: c.Task, Author: c.Author.String(), Body: c.Body, CreatedAt: timestamp(c.CreatedAt),
	})
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) && pgErr.Code == foreignKeyViolation {
		return task.ErrTaskNotFound
	}
	return translate(err, "comment")
}

// Comments implements task.Repository.
func (r *Repository) Comments(ctx context.Context, org, id string) ([]task.Comment, error) {
	rows, err := db.New(r.pool).ListComments(ctx, db.ListCommentsParams{Org: org, TaskID: id})
	if err != nil {
		return nil, translate(err, "comments")
	}
	out := make([]task.Comment, len(rows))
	for i, row := range rows {
		author, err := grn.Parse(row.Author)
		if err != nil {
			return nil, errorx.Wrap(err, "tasks: stored author", errorx.KindDataLoss)
		}
		out[i] = task.Comment{ID: row.ID, Org: row.Org, Task: row.TaskID, Author: author, Body: row.Body, CreatedAt: row.CreatedAt.Time}
	}
	return out, nil
}
